CREATE TABLE public.companies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid GENERATED ALWAYS AS (id) STORED UNIQUE, name text NOT NULL, signature text NOT NULL DEFAULT '', reply_to_email text, inbound_address text NOT NULL UNIQUE, hourly_rate_ex_vat numeric NOT NULL DEFAULT 650 CHECK(hourly_rate_ex_vat >= 0), travel_fee numeric NOT NULL DEFAULT 450 CHECK(travel_fee >= 0), settings jsonb NOT NULL DEFAULT '[true,true,false,true,true,true,true]', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.companies TO authenticated; GRANT ALL ON public.companies TO service_role;
ALTER TABLE public.companies ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.company_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id), user_id uuid NOT NULL UNIQUE REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('ägare','användare')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,user_id));
GRANT SELECT ON public.company_members TO authenticated; GRANT ALL ON public.company_members TO service_role;
ALTER TABLE public.company_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY member_read ON public.company_members FOR SELECT TO authenticated USING(user_id = auth.uid());
CREATE FUNCTION public.my_company() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT company_id FROM public.company_members WHERE user_id = auth.uid() $$;
REVOKE ALL ON FUNCTION public.my_company() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.my_company() TO authenticated;
CREATE POLICY company_read ON public.companies FOR SELECT TO authenticated USING(id = public.my_company());
CREATE POLICY company_update ON public.companies FOR UPDATE TO authenticated USING(id = public.my_company()) WITH CHECK(id = public.my_company());
CREATE TABLE public.moments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id), name text NOT NULL, unit text NOT NULL, hours_per_unit numeric NOT NULL CHECK(hours_per_unit >= 0), material_per_unit_ex_vat numeric NOT NULL CHECK(material_per_unit_ex_vat >= 0), role text NOT NULL DEFAULT 'elektriker', rot_eligible boolean NOT NULL DEFAULT true, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.moments TO authenticated; GRANT ALL ON public.moments TO service_role;
ALTER TABLE public.moments ENABLE ROW LEVEL SECURITY;
CREATE POLICY moments_company ON public.moments FOR ALL TO authenticated USING(company_id=public.my_company()) WITH CHECK(company_id=public.my_company());
CREATE TABLE public.customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id), name text NOT NULL, email text, phone text, address text, place text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.customers TO authenticated; GRANT ALL ON public.customers TO service_role;
ALTER TABLE public.customers ENABLE ROW LEVEL SECURITY;
CREATE POLICY customers_company ON public.customers FOR ALL TO authenticated USING(company_id=public.my_company()) WITH CHECK(company_id=public.my_company());
CREATE TABLE public.threads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id), customer_id uuid NOT NULL, job text NOT NULL, place text, channel text NOT NULL CHECK(channel IN ('email','sms','wa','form')), status text NOT NULL DEFAULT 'svar' CHECK(status IN ('analys','svar','ai','skickad','oppnad','bokat','vunnen')), read boolean NOT NULL DEFAULT false, autopilot boolean NOT NULL DEFAULT false, why text NOT NULL DEFAULT '', asks jsonb NOT NULL DEFAULT '[]', facts jsonb NOT NULL DEFAULT '[]', last_message_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,id), FOREIGN KEY(company_id,customer_id) REFERENCES public.customers(company_id,id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.threads TO authenticated; GRANT ALL ON public.threads TO service_role;
ALTER TABLE public.threads ENABLE ROW LEVEL SECURITY;
CREATE POLICY threads_company ON public.threads FOR ALL TO authenticated USING(company_id=public.my_company()) WITH CHECK(company_id=public.my_company());
CREATE TABLE public.messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id), thread_id uuid NOT NULL, "from" text NOT NULL CHECK("from" IN ('kund','vv','ai','sys')), channel text, text text NOT NULL, attachments jsonb NOT NULL DEFAULT '[]', provider_message_id text, in_reply_to text, sent_at timestamptz NOT NULL DEFAULT now(), approved_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(company_id,thread_id) REFERENCES public.threads(company_id,id));
GRANT SELECT ON public.messages TO authenticated; GRANT ALL ON public.messages TO service_role;
ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY messages_company ON public.messages FOR SELECT TO authenticated USING(company_id=public.my_company());
CREATE TABLE public.quotes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id), thread_id uuid NOT NULL, nr text NOT NULL, version integer NOT NULL DEFAULT 1, owners integer NOT NULL DEFAULT 1 CHECK(owners IN (1,2)), add_on boolean NOT NULL DEFAULT false, prisform text NOT NULL DEFAULT 'fast' CHECK(prisform IN ('fast','ungefar')), lines jsonb NOT NULL DEFAULT '[]', status text NOT NULL DEFAULT 'utkast', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(thread_id,version), FOREIGN KEY(company_id,thread_id) REFERENCES public.threads(company_id,id));
GRANT SELECT ON public.quotes TO authenticated; GRANT ALL ON public.quotes TO service_role;
ALTER TABLE public.quotes ENABLE ROW LEVEL SECURITY;
CREATE POLICY quotes_company ON public.quotes FOR SELECT TO authenticated USING(company_id=public.my_company());
CREATE TABLE public.drafts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id), thread_id uuid NOT NULL UNIQUE, text text NOT NULL DEFAULT '', variant text NOT NULL DEFAULT 'std', channel text NOT NULL DEFAULT 'email', attachments jsonb NOT NULL DEFAULT '[]', edited boolean NOT NULL DEFAULT false, warnings jsonb NOT NULL DEFAULT '[]', needs_review boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(company_id,thread_id) REFERENCES public.threads(company_id,id));
GRANT SELECT, INSERT, UPDATE ON public.drafts TO authenticated; GRANT ALL ON public.drafts TO service_role;
ALTER TABLE public.drafts ENABLE ROW LEVEL SECURITY;
CREATE POLICY drafts_company ON public.drafts FOR ALL TO authenticated USING(company_id=public.my_company()) WITH CHECK(company_id=public.my_company());
CREATE TABLE public.audit_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id), user_id uuid NOT NULL, event text NOT NULL, "before" jsonb, "after" jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_log TO authenticated; GRANT ALL ON public.audit_log TO service_role;
ALTER TABLE public.audit_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_company ON public.audit_log FOR SELECT TO authenticated USING(company_id=public.my_company());
CREATE FUNCTION public.estim_touch() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['companies','company_members','moments','customers','threads','messages','quotes','drafts','audit_log'] LOOP EXECUTE format('CREATE TRIGGER touch_updated_at BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.estim_touch()',t); END LOOP; END $$;
CREATE FUNCTION public.estim_onboard(payload jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; item jsonb; BEGIN
IF auth.uid() IS NULL OR public.my_company() IS NOT NULL THEN RAISE EXCEPTION 'Not allowed'; END IF;
IF length(trim(payload->>'name')) < 1 THEN RAISE EXCEPTION 'Company name required'; END IF;
cid=gen_random_uuid();
INSERT INTO public.companies(id,name,signature,reply_to_email,inbound_address,hourly_rate_ex_vat,travel_fee) VALUES(cid,trim(payload->>'name'),coalesce(payload->>'signature',''),auth.jwt()->>'email',cid::text||'@in.estim.se',(payload->>'hourly_rate_ex_vat')::numeric,(payload->>'travel_fee')::numeric);
INSERT INTO public.company_members(company_id,user_id,role) VALUES(cid,auth.uid(),'ägare');
IF jsonb_array_length(payload->'moments') != 10 THEN RAISE EXCEPTION 'Ten initial moments required'; END IF;
FOR item IN SELECT * FROM jsonb_array_elements(payload->'moments') LOOP
INSERT INTO public.moments(company_id,name,unit,hours_per_unit,material_per_unit_ex_vat,role,rot_eligible,active) VALUES(cid,item->>'name',item->>'unit',(item->>'hours_per_unit')::numeric,(item->>'material_per_unit_ex_vat')::numeric,coalesce(item->>'role','elektriker'),coalesce((item->>'rot_eligible')::boolean,true),true); END LOOP;
RETURN cid; END $$;
REVOKE ALL ON FUNCTION public.estim_onboard(jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.estim_onboard(jsonb) TO authenticated;
CREATE FUNCTION public.estim_request(payload jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid=public.my_company(); customer uuid; tid uuid; BEGIN
IF cid IS NULL OR length(trim(payload->>'name'))<1 OR length(trim(payload->>'text'))<1 THEN RAISE EXCEPTION 'Invalid request'; END IF;
INSERT INTO public.customers(company_id,name,email,phone,address,place) VALUES(cid,payload->>'name',payload->>'email',payload->>'phone',payload->>'address',payload->>'place') RETURNING id INTO customer;
INSERT INTO public.threads(company_id,customer_id,job,place,channel,status) VALUES(cid,customer,coalesce(payload->>'job','Ny förfrågan'),payload->>'place',payload->>'channel','svar') RETURNING id INTO tid;
INSERT INTO public.messages(company_id,thread_id,"from",channel,text) VALUES(cid,tid,'kund',payload->>'channel',payload->>'text');
INSERT INTO public.drafts(company_id,thread_id,channel,text,needs_review) VALUES(cid,tid,CASE WHEN payload->>'channel'='form' THEN 'email' ELSE payload->>'channel' END,'',true);
INSERT INTO public.audit_log(company_id,user_id,event,"after") VALUES(cid,auth.uid(),'Förfrågan skapad',jsonb_build_object('thread_id',tid)); RETURN tid; END $$;
REVOKE ALL ON FUNCTION public.estim_request(jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.estim_request(jsonb) TO authenticated;
CREATE FUNCTION public.estim_quote(tid uuid,payload jsonb) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid=public.my_company(); old public.quotes; ver integer; line jsonb; BEGIN
PERFORM 1 FROM public.threads WHERE id=tid AND company_id=cid FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Not allowed'; END IF;
IF jsonb_typeof(payload->'lines') != 'array' THEN RAISE EXCEPTION 'Invalid lines'; END IF;
FOR line IN SELECT * FROM jsonb_array_elements(payload->'lines') LOOP IF coalesce((line->>'q')::numeric,-1)<0 OR coalesce((line->>'p')::numeric,-1)<0 OR length(trim(line->>'t'))<1 THEN RAISE EXCEPTION 'Invalid quote line'; END IF; END LOOP;
SELECT * INTO old FROM public.quotes WHERE thread_id=tid ORDER BY version DESC LIMIT 1;
ver=coalesce(old.version,0)+1;
INSERT INTO public.quotes(company_id,thread_id,nr,version,owners,add_on,prisform,lines,status) VALUES(cid,tid,coalesce(old.nr,payload->>'nr'),ver,(payload->>'owners')::integer,coalesce((payload->>'addOn')::boolean,false),payload->>'prisform',payload->'lines','utkast');
INSERT INTO public.audit_log(company_id,user_id,event,"before","after") VALUES(cid,auth.uid(),'Offert ändrad',to_jsonb(old),jsonb_build_object('thread_id',tid,'version',ver,'quote',payload));
RETURN ver; END $$;
REVOKE ALL ON FUNCTION public.estim_quote(uuid,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.estim_quote(uuid,jsonb) TO authenticated;
CREATE FUNCTION public.estim_approve(tid uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid=public.my_company(); d public.drafts; mid uuid; BEGIN
PERFORM 1 FROM public.threads WHERE id=tid AND company_id=cid FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Not allowed'; END IF;
SELECT * INTO d FROM public.drafts WHERE thread_id=tid AND company_id=cid FOR UPDATE;
IF NOT FOUND OR length(trim(d.text))=0 THEN RAISE EXCEPTION 'Draft required'; END IF;
INSERT INTO public.messages(company_id,thread_id,"from",channel,text,attachments,approved_by) VALUES(cid,tid,'vv',d.channel,d.text,d.attachments,auth.uid()) RETURNING id INTO mid;
UPDATE public.threads SET status='skickad',read=true,last_message_at=now() WHERE id=tid;
DELETE FROM public.drafts WHERE id=d.id;
INSERT INTO public.audit_log(company_id,user_id,event,"before","after") VALUES(cid,auth.uid(),'Svar godkänt',to_jsonb(d),jsonb_build_object('message_id',mid,'thread_id',tid,'delivered',false)); RETURN mid; END $$;
REVOKE ALL ON FUNCTION public.estim_approve(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.estim_approve(uuid) TO authenticated;